#!/bin/bash
# exp 0369 K3: analyse (only if before 22:57:00), copy the summaries, then delete unviewed and release by 22:58
S=/c/Users/kjani/AppData/Local/Temp/claude/C--Users-kjani-Downloads-bc5/19eb012d-ed8a-4416-af2a-d3b1f4ce12f0/scratchpad
R=/c/Users/kjani/Downloads/bc5/bc5-exp0369/experiments/0369-lake-last-burst-writer/raw
ssh -o BatchMode=yes bc250 'cd ~/bc5-work/exp0369 || exit 1; grep -q "^water session exp 0369 | setup + lake bench K3" ../BOX-LOCK || { echo "our lock line is gone" >&2; exit 1; }; pgrep -a "^kyty_emulator" >&2 && { echo "emulator still up: no analysis" >&2; exit 1; }; if [ $(date +%H%M%S) -lt 225700 ]; then bash ana0369.sh K3 > K3.ana.log 2>&1; grep "^#" K3.tz.txt >&2; else echo "no time for the analysis: $(date +%T)" >&2; fi; gzip -c ~/bc5-data/priv/exp0369/K3/events.txt > K3.events.txt.gz; cp ~/bc5-data/priv/exp0369/K3/snaps.txt K3.snaps.txt; { cp r-K3/dmesg.txt K3.dmesg.txt 2>/dev/null || : > K3.dmesg.txt; }; tar cf - $(ls K3.out K3.bursts.txt K3.reads.txt K3.reads.json K3.tz.txt K3.events.txt.gz K3.snaps.txt K3.dmesg.txt 2>/dev/null)' > $S/k3raw.tar 2> $S/k3post.txt
echo "post exit $?"; cat $S/k3post.txt
ssh -o BatchMode=yes bc250 'set -u; cd ~/bc5-work || exit 1; grep -q "^water session exp 0369 | setup + lake bench K3" BOX-LOCK || echo "our lock line is gone"; pgrep -a "^kyty_emulator"; pgrep -af "play-pkg-0369|bc5-mount" | grep -v pgrep | cut -c1-120; du -sh ~/bc5-data/priv/exp0369/K3 exp0369/r-K3/shots | cut -f1 | tr "\n" " "; ls exp0369/r-K3/shots | wc -l; rm -rf ~/bc5-data/priv/exp0369/K3 && rm -rf exp0369/r-K3/shots && echo "deleted snapshots and shots (unviewed)"; ls ~/bc5-data/priv/exp0369/; cat exp0369/r-K3/journal-dir.txt; cd _SaveData && S=$(find PPSA03671 -type f -exec md5sum {} + | sort -k2 | md5sum | cut -c1-16); echo "live saves $S"; cd ..; P=$(cat exp0369/kstream.pid); ps -o pid=,args= -p $P; kill $P && echo "killed our journalctl $P"; sed -i "/^water session exp 0369 | setup + lake bench K3/d" BOX-LOCK; echo "water exp 0369 | released: run K3 done (RT on, live saves $S); snapshots and shots deleted unviewed, the journal private | $(date "+%F %T")" >> BOX-QUEUE; echo "--- BOX-LOCK:"; cat BOX-LOCK; tail -1 BOX-QUEUE; date +%T'
mkdir -p $R && tar xf $S/k3raw.tar -C $R && cp $S/K3.ab.txt $R/K3.ab.txt && cp $S/K3.pl.txt $R/K3.pl.txt && ls -la $R | grep K3 | awk '{print $5, $9}'
